def marginal_rows(phis, order_vars):
    """Exact numerators and common denominator Z for every core variable."""
    plan = build_plan(phis, order_vars)
    total = run_plan(plan, phis)
    if total == 0:
        return None
    n = len(phis)
    touched = [set() for _ in range(n)]
    for e in range(n):
        scope = phis[e][0]
        for var in scope:
            touched[var].add(e)
    rows = [None] * n
    for var in range(n):
        scope = phis[var][0]
        if len(scope) == 1 and len(touched[var]) == 1:
            row = phis[var][1]
            s = row[0] + row[1] + row[2]
            if s > 0:
                rows[var] = (row[0], row[1], row[2], s)
                continue
        first = run_plan(plan, phis, (var, C2P))
        second = run_plan(plan, phis, (var, P2P))
        third = total - first - second
        if third < 0:
            third = 0
        rows[var] = (first, second, third, total)
    return rows


