def triple_legitimacy(left, right):
    """Exact (numerator, denominator) of U + D - U*D; no reduction needed."""
    nu, du = left[C2P]
    nd, dd = right[P2C]
    return (nu * dd + nd * du - nu * nd, du * dd)


def full_legitimacy(vectors):
    """Sum of products over c2p* p2c* and c2p* p2p p2c*, as a float."""
    state_c = 1.0
    state_d = 0.0
    state_p = 0.0
    for vec in vectors:
        pc = vec[C2P][0] / vec[C2P][1]
        pp = vec[P2P][0] / vec[P2P][1]
        pd = vec[P2C][0] / vec[P2C][1]
        state_c, state_d, state_p = (state_c * pc,
                                     (state_c + state_d) * pd,
                                     state_c * pp + state_p * pd)
    out = state_c + state_d + state_p
    if not math.isfinite(out) or out < 0.0:
        return 0.0
    return 1.0 if out > 1.0 else out


def one_hot(state, forward):
    vec = [(0, 1), (0, 1), (0, 1)]
    vec[state] = (1, 1)
    if not forward:
        vec = (vec[2], vec[1], vec[0])
    else:
        vec = tuple(vec)
    return vec


def lookup(link, forward, declared, marginals, priors):
    vec = declared.get(link)
    if vec is None:
        mar = marginals.get(link)
        if mar is not None:
            n0, n1, n2, den = mar
            vec = ((n0, den), (n1, den), (n2, den))
        else:
            vec = priors.get(link)
            if vec is None:
                vec = ((1, 3), (1, 3), (1, 3))
    return vec if forward else (vec[2], vec[1], vec[0])
